// Updates, soft deletes and restorations record assigned or changed fields plus the key; create and delete record every field.
// Standalone Compare results have no captured operation and cannot become lifecycle audit records.
func (changes ProjectChanges) Audit(policy ProjectAuditPolicy) (record.Model[Project, model.ID[Project]], error) {
	operation, present := changes.operation.Get()
	if !present {
		return record.Model[Project, model.ID[Project]]{}, foundryfault.New(foundryfault.Missing, "audit requires captured model changes")
	}
	item, present := changes.after.Get()
	if !present {
		item, present = changes.before.Get()
	}
	if !present {
		return record.Model[Project, model.ID[Project]]{}, foundryfault.New(foundryfault.Missing, "audit requires a stored model snapshot")
	}
	builder, err := record.NewBuilder(item.FoundryReference(), operation, "id", policy.ID)
	if err != nil {
		return record.Model[Project, model.ID[Project]]{}, err
	}
	if err = record.Capture(builder, "id", codec.ID[Project](), changes.fields.ID, policy.ID); err != nil {
		return record.Model[Project, model.ID[Project]]{}, err
	}
	if err = record.Capture(builder, "name", codec.String[string](), changes.fields.Name, policy.Name); err != nil {
		return record.Model[Project, model.ID[Project]]{}, err
	}
	return builder.Build()
}

// ProjectAuditFieldSet contains typed historical fields. An omitted field differs from an absent model or SQL NULL.
type ProjectAuditFieldSet struct {
	_ [0]*Project
	// ID retains stored hook_projects.id after write mutators; read accessors do not replace audit values.
	ID foundryvalue.Optional[record.FieldChange[model.ID[Project]]]
	// Name retains stored hook_projects.name after write mutators; read accessors do not replace audit values.
	Name foundryvalue.Optional[record.FieldChange[string]]
}

// ProjectAuditFields reads model-owned history through its declared codecs, without populating a partial model.
// Get on a redacted field reports an explicit error; its Snapshot remains available for deliberate audit export.
func ProjectAuditFields(history record.Model[Project, model.ID[Project]]) (ProjectAuditFieldSet, error) {
	view, err := record.Inspect(history)
	if err != nil {
		return ProjectAuditFieldSet{}, err
	}
	var fields ProjectAuditFieldSet
	fields.ID, err = record.ReadField(view, "id", codec.ID[Project]())
	if err != nil {
		return ProjectAuditFieldSet{}, err
	}
	fields.Name, err = record.ReadField(view, "name", codec.String[string]())
	if err != nil {
		return ProjectAuditFieldSet{}, err
	}
	return fields, nil
}

// ProjectAuditing declares automatic auditing for normal lifecycle writes. Register it once through audit.Register.
// Existing observer registration owns dependency construction, duplicate detection and transaction lifetime.
func ProjectAuditing(policy ProjectAuditPolicy) record.Declaration {
	return record.Declare(func(registrar *foundation.Registrar, pool foundation.Key[*database.DB], resolve record.ResolveWriter) error {
		name, err := record.ObserverName[Project]()
		if err != nil {
			return err
		}
		return RegisterProjectObserver(registrar, pool, NewProjectObserver(name), func(resolver foundation.Resolver) (func() ProjectHooks, error) {
			writer, err := resolve(resolver)
			if err != nil {
				return nil, err
			}
			if writer == nil {
				return nil, foundryfault.New(foundryfault.Invalid, "audit writer is not initialized")
			}
			return func() ProjectHooks {
				write := func(ctx context.Context, tx *database.Tx, changes ProjectChanges) error {
					captured, err := changes.Audit(policy)
					if err != nil {
						return err
					}
					return writer.RecordModel(ctx, tx, captured.Entry())
				}
				return ProjectHooks{Created: write, Updated: write, Deleted: write, Restored: write}
			}, nil
		})
	})
}
